"""Array alias models generated by hook 0800 (e.g. ``TagSet``) validate their items (#394)."""

from __future__ import annotations

import pytest
from pathlib import Path
from typing import Any

from pydantic import ValidationError


def test_semantic_item_alias_model_builds_and_brands_items():
    from camunda_orchestration_sdk.models.tag_set import TagSet
    from camunda_orchestration_sdk.semantic_types import Tag

    tags = TagSet.model_validate(["alpha", "beta:1"])

    assert tags.root == ["alpha", "beta:1"]
    assert all(type(tag) is Tag for tag in tags.root)
    assert tags.model_dump() == ["alpha", "beta:1"]
    assert TagSet.model_json_schema()["type"] == "array"


@pytest.mark.parametrize(
    ("items", "message"),
    [
        ([1], "expected str"),
        (["1starts-with-digit"], "pattern"),
        (["dup", "dup"], "uniqueItems"),
        ([f"t{i}" for i in range(11)], "maxItems 10"),
    ],
)
def test_semantic_item_alias_model_rejects_invalid_items(items: list[object], message: str):
    from camunda_orchestration_sdk.models.tag_set import TagSet

    with pytest.raises(ValidationError, match=message):
        TagSet.model_validate(items)


def test_item_error_messages_interpolate_the_index():
    """No generated model may carry a literal ``{_i}``: the index must be interpolated."""
    import ast

    import camunda_orchestration_sdk

    models_dir = Path(camunda_orchestration_sdk.__file__).parent / "models"
    offenders: list[str] = []
    for model_file in sorted(models_dir.glob("*.py")):
        tree = ast.parse(model_file.read_text(encoding="utf-8"))
        joined_parts = {
            id(part)
            for node in ast.walk(tree)
            if isinstance(node, ast.JoinedStr)
            for part in node.values
        }
        offenders.extend(
            f"{model_file.name}:{node.lineno}"
            for node in ast.walk(tree)
            if isinstance(node, ast.Constant)
            and isinstance(node.value, str)
            and "{_i}" in node.value
            and id(node) not in joined_parts
        )

    assert not offenders, f"Literal '{{_i}}' in item error messages: {offenders}"


def test_semantic_item_schema_is_explicit_for_old_pydantic():
    """Items carry an explicit JSON schema so pydantic<2.9 can build it (PlainValidator)."""
    from camunda_orchestration_sdk.models.tag_set import TagSet

    assert TagSet.model_json_schema()["items"]["type"] == "string"


@pytest.mark.parametrize(
    ("item_type", "py_base", "good", "bad"),
    [
        ("integer", "int", 1, "1"),
        ("number", "float", 1.5, "1.5"),
        ("string", "str", "a", 1),
    ],
)
def test_hook_semantic_item_validator_uses_declared_type(
    tmp_path: Path, item_type: str, py_base: str, good: object, bad: object
):
    """The emitted per-item validator must check the item's declared primitive type."""
    mod = _generate_semantic_array_model(tmp_path, item_type, py_base)
    model = mod.SemSet.model_validate([good])
    assert type(model.root[0]).__name__ == "Sem"
    assert mod.SemSet.model_json_schema()["items"]["type"] == item_type
    with pytest.raises(ValidationError, match=f"expected {py_base}"):
        mod.SemSet.model_validate([bad])
    if py_base != "str":
        with pytest.raises(ValidationError):
            mod.SemSet.model_validate([True])


def _generate_semantic_array_model(tmp_path: Path, item_type: str, py_base: str) -> Any:
    """Run hook 0800 with a semantic item type and import the generated model module."""
    import importlib.util
    import sys
    import types

    hooks_dir = Path(__file__).resolve().parents[2] / "hooks" / "post_gen"
    sys.path.insert(0, str(hooks_dir.parent))
    sys.path.insert(0, str(hooks_dir))
    try:
        spec = importlib.util.spec_from_file_location(
            "_hook0800", hooks_dir / "0800_generate_composite_alias_models.py"
        )
        assert spec and spec.loader
        hook: Any = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(hook)
    finally:
        sys.path[:2] = []

    pkg = tmp_path / "pkg"
    (pkg / "models").mkdir(parents=True)
    (pkg / "__init__.py").write_text("")
    (pkg / "models" / "__init__.py").write_text("")
    (pkg / "semantic_types.py").write_text(f"class Sem({py_base}):\n\tpass\n")
    hook._emit_array_alias_model(
        pkg / "models", "SemSet", {"type": item_type, "x-semantic-type": "Sem"}, {}
    )
    sys.path.insert(0, str(tmp_path))
    try:
        for m in [k for k in sys.modules if k == "pkg" or k.startswith("pkg.")]:
            del sys.modules[m]
        mod: Any = importlib.import_module("pkg.models.sem_set")
    finally:
        sys.path.remove(str(tmp_path))
    assert isinstance(mod, types.ModuleType)
    return mod


def test_number_semantic_array_accepts_int_items(tmp_path: Path):
    """A ``number`` semantic array must brand integer input, not raise TypeError (#397).

    Hook 0700 generates ``float`` subclasses whose ``__new__`` rejects ``int``; the
    hook 0800 item validator accepts ``int`` for ``number`` items, so it must cast
    to ``float`` before construction. Uses a real hook-0700-generated class.
    """
    import importlib.util
    import sys
    import types

    hooks_dir = Path(__file__).resolve().parents[2] / "hooks" / "post_gen"
    sys.path.insert(0, str(hooks_dir.parent))
    sys.path.insert(0, str(hooks_dir))
    try:

        def _load(name: str, path: Path) -> Any:
            spec = importlib.util.spec_from_file_location(name, path)
            assert spec and spec.loader
            m: Any = importlib.util.module_from_spec(spec)
            spec.loader.exec_module(m)
            return m

        hook7 = _load("_hook0700", hooks_dir / "0700_generate_semantic_types.py")
        hook8 = _load("_hook0800", hooks_dir / "0800_generate_composite_alias_models.py")
    finally:
        sys.path[:2] = []

    out = tmp_path / "gen"
    hook7._emit_semantic_types_py(out, {"Score": {"type": "number", "constraints": {}}}, None)
    sdk = out / "camunda_orchestration_sdk"
    models_dir = sdk / "models"
    models_dir.mkdir(parents=True, exist_ok=True)
    hook8._emit_array_alias_model(
        models_dir, "ScoreSet", {"type": "number", "x-semantic-type": "Score"}, {}
    )

    # Exec the generated module with a stub ``semantic_types`` package supplying the
    # hook-0700 class, avoiding any import of the installed camunda_orchestration_sdk.
    sem: Any = types.ModuleType("semantic_types")
    exec(sdk.joinpath("semantic_types.py").read_text(encoding="utf-8"), sem.__dict__)
    sys.modules["semantic_types"] = sem
    try:
        src = models_dir.joinpath("score_set.py").read_text(encoding="utf-8")
        src = src.replace("from ..semantic_types import", "from semantic_types import")
        mod: Any = types.ModuleType("score_set")
        exec(compile(src, "score_set.py", "exec"), mod.__dict__)
    finally:
        del sys.modules["semantic_types"]

    model = mod.ScoreSet.model_validate([1])
    assert type(model.root[0]).__name__ == "Score"
    assert model.root[0] == 1.0
    assert isinstance(model.root[0], float)
